import { createHmac, timingSafeEqual } from "node:crypto";

const SECRET_KEY = "secret_key_123";

export interface JwtPayload {
  username: string;
  role: string;
  [key: string]: unknown;
}

function base64UrlEncode(input: string): string {
  return Buffer.from(input, "utf-8")
    .toString("base64")
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

function base64UrlDecode(input: string): string {
  let base64 = input.replace(/-/g, "+").replace(/_/g, "/");
  const pad = base64.length % 4;
  if (pad === 2) {
    base64 += "==";
  } else if (pad === 3) {
    base64 += "=";
  } else if (pad !== 0) {
    throw new Error("Invalid base64url string");
  }
  return Buffer.from(base64, "base64").toString("utf-8");
}

function sign(data: string): string {
  return createHmac("sha256", SECRET_KEY)
    .update(data)
    .digest("base64")
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

/**
 * Creates a signed JWT (HMAC-SHA256) using the given payload.
 */
export function createJwt(payload: JwtPayload): string {
  const header = { alg: "HS256", typ: "JWT" };
  const encodedHeader = base64UrlEncode(JSON.stringify(header));
  const encodedPayload = base64UrlEncode(JSON.stringify(payload));
  const signature = sign(`${encodedHeader}.${encodedPayload}`);
  return `${encodedHeader}.${encodedPayload}.${signature}`;
}

/**
 * Verifies the signature of a JWT and returns the decoded payload if valid.
 * Returns null if the token is missing, malformed, or has an invalid signature.
 */
export function verifyJwt(token: string | undefined | null): JwtPayload | null {
  if (!token) {
    return null;
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return null;
  }

  const [encodedHeader, encodedPayload, signature] = parts;

  const expectedSignature = sign(`${encodedHeader}.${encodedPayload}`);

  const signatureBuffer = Buffer.from(signature);
  const expectedSignatureBuffer = Buffer.from(expectedSignature);

  if (signatureBuffer.length !== expectedSignatureBuffer.length) {
    return null;
  }

  if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
    return null;
  }

  try {
    const payload = JSON.parse(base64UrlDecode(encodedPayload)) as JwtPayload;
    return payload;
  } catch {
    return null;
  }
}

import { component$, Slot } from "@builder.io/qwik";
import type { RequestHandler } from "@builder.io/qwik-city";
import { verifyJwt } from "~/lib/jwt";

/**
 * Authentication middleware for all routes under `/admin/*`.
 *
 * - Checks for the presence of the `jwt_token` cookie.
 * - Verifies the HMAC-SHA256 signature of the token.
 * - Ensures the decoded payload has a `role` of `"admin"`.
 * - Redirects to `/login` with a 302 status if any of the above checks fail.
 */
export const onRequest: RequestHandler = (requestEvent) => {
  const token = requestEvent.cookie.get("jwt_token")?.value;
  const payload = verifyJwt(token);

  if (!payload || payload.role !== "admin") {
    throw requestEvent.redirect(302, "/login");
  }

  // Make the authenticated payload available to child routes.
  requestEvent.sharedMap.set("authUser", payload);
};

export default component$(() => {
  return <Slot />;
});

