import { component$ } from "@builder.io/qwik";
import type { DocumentHead, RequestHandler } from "@builder.io/qwik-city";
import { createJwt } from "~/lib/jwt";

const VALID_USERNAME = "admin";
const VALID_PASSWORD = "password123";

interface Credentials {
  username?: unknown;
  password?: unknown;
}

export const onPost: RequestHandler = async (requestEvent) => {
  const contentType = requestEvent.request.headers.get("content-type") ?? "";

  let credentials: Credentials = {};

  if (contentType.includes("application/json")) {
    credentials = (await requestEvent.request.clone().json()) as Credentials;
  } else {
    // Handles `application/x-www-form-urlencoded` (and multipart/form-data)
    const body = await requestEvent.parseBody();
    credentials = body as Credentials;
  }

  const username = typeof credentials.username === "string" ? credentials.username : "";
  const password = typeof credentials.password === "string" ? credentials.password : "";

  if (username === VALID_USERNAME && password === VALID_PASSWORD) {
    const token = createJwt({ username: VALID_USERNAME, role: "admin" });

    requestEvent.cookie.set("jwt_token", token, {
      path: "/",
      httpOnly: true,
      sameSite: "lax",
    });

    throw requestEvent.redirect(302, "/admin/dashboard");
  }

  requestEvent.json(401, { error: "Invalid credentials" });
};

